        TextRenderer.DrawText(g,"不透明度 "+Options.Opacity+"% · 保存后应用",small,new Rectangle(20,406,Width-40,50),C(139,158,184),TextFormatFlags.WordBreak);e.Graphics.Clear(Parent?.BackColor??BarcaUi.Canvas);using var alpha=new System.Drawing.Imaging.ImageAttributes();alpha.SetColorMatrix(new System.Drawing.Imaging.ColorMatrix{Matrix33=Options.Opacity/100f});e.Graphics.DrawImage(surface,ClientRectangle,0,0,surface.Width,surface.Height,GraphicsUnit.Pixel,alpha);var kit=AnimationSkin.Name(Skin);if(kit!=null)KitPalette.Draw(e.Graphics,atlas,new RectangleF(69,70,166,180),new RectangleF(0,0,192,208),kit,1);else e.Graphics.DrawImage(atlas,new Rectangle(69,70,166,180),new Rectangle(0,0,192,208),GraphicsUnit.Pixel);}
